python3 - <<'Q'
p='site/index.html';s=open(p).read()
css="<style id=\"bootGold\">html body .glogo::after{color:#e9b649!important;background:linear-gradient(180deg,#fff2b8 0%,#f3cd63 30%,#c8902a 62%,#8a5a16 100%)!important;-webkit-background-clip:text!important;background-clip:text!important;-webkit-text-fill-color:transparent!important;filter:drop-shadow(0 2px 0 #4a2f08) drop-shadow(0 4px 6px rgba(0,0,0,.7))!important;text-shadow:none!important}html body .glogo::before{color:rgb(var(--uiA,242,193,78))!important;text-shadow:0 0 8px rgba(var(--uiA,242,193,78),.6)!important;font-weight:800!important;letter-spacing:.32em!important}</style><script>try{var h=String(localStorage.getItem('glen_uiTheme')||'').replace('#','');if(/^[0-9a-f]{6}$/i.test(h)){var n=parseInt(h,16);document.documentElement.style.setProperty('--uiA',(n>>16&255)+','+(n>>8&255)+','+(n&255))}}catch(e){}</script>"
assert s.count('</head>')>=1; i=s.index('</head>'); s=s[:i]+css+s[i:]
s=s.replace('name="theme-color" content="#101612"','name="theme-color" content="#1a1206"')
open(p,'w').write(s)
Q
cp site/index.html /tmp/srv/new216.html
